import { Component, computed, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzInputModule } from 'ng-zorro-antd/input';
import { TablerIconComponent, IconX } from '@tabler/icons-angular';
import { HrmControl } from '../shared/hrm-control';

export type HrmSize = 'sm' | 'md' | 'lg';
export type HrmStatus = '' | 'error' | 'warning' | 'success';
/** nz-* nzStatus chỉ nhận ''|error|warning. 'success' render riêng qua class .hrm-status-success (bridge CSS xanh). */
export type NzStatus = '' | 'error' | 'warning';
export const toNzStatus = (s: HrmStatus): NzStatus => (s === 'success' ? '' : s);

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-input — text input bọc nz-input + CVA. Hỗ trợ [(ngModel)]/formControl.
 *  prefixIcon (Tabler object) + clearable (nút xóa) → dùng nz-input-group affix.
 *  Dùng: <hrm-input [(ngModel)]="name" placeholder="Họ tên" [prefixIcon]="IconSearch" [clearable]="true" /> */
@Component({
  selector: 'hrm-input',
  imports: [FormsModule, NzInputModule, TablerIconComponent],
  template: `
    @if (hasAffix()) {
      <nz-input-group [nzPrefix]="prefixIcon() ? preTpl : undefined" [nzSuffix]="sufTpl"
        [nzSize]="toNz(size())" [nzStatus]="toNzStatus(status())">
        <input
          nz-input
          [ngModel]="value()"
          (ngModelChange)="emit($event)"
          (blur)="markTouched()"
          [placeholder]="placeholder()"
          [readOnly]="readonly()"
          [disabled]="disabled()"
          [type]="htmlType()"
          [attr.maxlength]="maxlength()" />
      </nz-input-group>
      <ng-template #preTpl><tabler-icon [icon]="$any(prefixIcon())" [size]="16" class="hrm-input-pre" /></ng-template>
      <ng-template #sufTpl>
        @if (clearable() && !!value()) {
          <button type="button" class="hrm-input-clear" (click)="clear()" [attr.aria-label]="clearLabel() || null">
            <tabler-icon [icon]="xIcon" [size]="14" />
          </button>
        }
      </ng-template>
    } @else {
      <input
        nz-input
        [ngModel]="value()"
        (ngModelChange)="emit($event)"
        (blur)="markTouched()"
        [placeholder]="placeholder()"
        [nzSize]="toNz(size())"
        [nzStatus]="toNzStatus(status())"
        [readOnly]="readonly()"
        [disabled]="disabled()"
        [type]="htmlType()"
        [attr.maxlength]="maxlength()" />
    }
  `,
  styles: [`
.hrm-input-pre { color: var(--icon-secondary, var(--text-sub)); display: inline-flex; }
.hrm-input-clear {
  display: inline-flex; align-items: center; justify-content: center;
  border: 0; padding: 0; background: transparent; cursor: pointer;
  color: var(--icon-secondary, var(--text-sub)); border-radius: var(--radius-sm);
}
.hrm-input-clear:hover { color: var(--text-strong); }
  `],
  host: { class: 'hrm-input', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmInput), multi: true }],
})
export class HrmInput extends HrmControl<string> {
  readonly placeholder = input('');
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  readonly readonly = input(false);
  readonly htmlType = input<'text' | 'password' | 'email' | 'tel' | 'url'>('text');
  readonly maxlength = input<number | null>(null);
  readonly prefixIcon = input<unknown>(null);
  readonly clearable = input(false);
  readonly clearLabel = input('');

  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;
  protected readonly xIcon = IconX;
  protected readonly hasAffix = computed(() => !!this.prefixIcon() || this.clearable());

  protected clear(): void { this.emit(''); }
}
